      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "तद्धीरो भव वित्तवत्सु कृपणां वृत्तिं वृथा मा कृथाः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "कूपे पश्य पयोनिधावपि घटो गृह्णाति तुल्यं जलम् ॥ ४९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "त्वमेव चातकाधारोसीति केषां न गोचरः ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "किमम्भोदवरास्माकं कार्पण्योक्तिः प्रतीक्ष्यते ॥ ५० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "रे रे चातक सावधानमनसा मित्र क्षणं श्रूयता-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "मम्भोदा बहवो हि सन्ति गगने सर्वेपि नैतादृशाः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "केचिद्वृष्टिभिरार्द्रयन्ति वसुधां गर्जन्ति केचिद्वृथा",
          "end": "line"
        },
        {
          "n": 4,
          "text": "यं यं पश्यसि तस्य तस्य पुरतो मा ब्रूहि दीनं वचः ॥ ५१ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "heading",
      "lines": [
        {
          "n": 1,
          "text": "",
          "end": "space"
        },
        {
          "n": 2,
          "text": "अथ दुर्जनप्रशंसा ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "अकरुणत्वमकारणविग्रहः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "परधने परयोषिति च स्पृहा ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "सुजनबन्धुजनेष्वसहिष्णुता",
          "end": "line"
        },
        {
          "n": 4,
          "text": "प्रकृतिसिद्धमिदं हि दुरात्मनाम् ॥ ५२ ॥",
          "end": "space"
        },
        {
          "n": 5,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
